import type { Record, TableName, TableSchemaDotWalk } from '../db'

/**
 * Type for ServiceNow related list identifiers.
 * Supports:
 * - System relationships: Record<'sys_relationship'> or REL:sys_id (GUID)
 * - Parent-child relationships: 'parent_table.child_table' format
 * - Direct string references
 */
type RelatedListId = string | Record<'sys_relationship'>

type uiType = 'desktop' | 'mobile-or-service-portal' | 'all'

type fieldMessageType = 'error' | 'info' | 'warning' | 'none'
/**
 * Type representing the action to be performed on a field by a UI Policy.
 * Action properties use ServiceNow string format ('true', 'false', 'ignore').
 */
type UiPolicyAction<T extends TableName> = {
    /** The field to which the action applies  */
    field: TableSchemaDotWalk<T>
    /** Whether the field should be visible */
    visible?: boolean | 'ignore'
    /** Whether the field should be read-only (disabled). Note: true means read-only/disabled, false means editable */
    readOnly?: boolean | 'ignore'
    /** Whether the field should be mandatory */
    mandatory?: boolean | 'ignore'
    /** Whether the field should be cleared when the condition is met */
    cleared?: boolean
    /** The table reference for the action (sys_db_object) */
    table?: T
    /** Value to set for the field */
    value?: string
    /** Message to display for the field */
    fieldMessage?: string
    /** Type of field message (e.g., 'error', 'info', 'warning') */
    fieldMessageType?: fieldMessageType
    /** Action to perform on the field value */
    valueAction?: string
}

/**
 * Type representing the action to be performed on a related list by a UI Policy.
 */
type UiPolicyRelatedListAction = {
    /**
     * The related list identifier. Supports:
     * - System relationships: 'REL:sys_id' where sys_id comes from Now.ID registry
     * - Parent-child relationships: 'parent_table.child_table' (e.g., 'incident.task')
     * - Empty/undefined: applies to all related lists
     */
    list?: RelatedListId
    /** Whether the related list should be visible */
    visible?: boolean | 'ignore'
}
/**
 * Type representing the complete configuration of a UI Policy with metadata.
 */
type UiPolicy<T extends TableName> = Now.Internal.WithID<{
    /** The table to which the UI Policy applies (optional) */
    table?: T
    /** A brief description of what the UI Policy does (required and must not be empty) */
    shortDescription: string
    /** Whether the UI Policy is active */
    active?: boolean
    /** Whether the UI Policy applies globally across all applications */
    global?: boolean
    /** Whether the UI Policy runs when the form loads */
    onLoad?: boolean
    /** Whether to reverse the actions when the condition is false (renamed from 'reverse' for clarity) */
    reverseIfFalse?: boolean
    /** Whether the UI Policy is inherited by tables that extend this table */
    inherit?: boolean
    /** A condition script or query that determines when the UI Policy applies */
    conditions?: string
    /** List of actions to perform when the UI Policy condition is met */
    actions?: UiPolicyAction<T>[]
    /** List of related list visibility controls */
    relatedListActions?: UiPolicyRelatedListAction[]
    /** Detailed description of the UI Policy */
    description?: string
    /** Model ID for the UI Policy */
    modelId?: string
    /** Model table for the UI Policy */
    modelTable?: T
    /** Order/priority of the UI Policy execution */
    order?: number
    /** Whether to run the scripts defined in scriptTrue/scriptFalse */
    runScripts?: boolean
    /** JavaScript code that runs when the condition evaluates to true */
    scriptTrue?: string
    /** JavaScript code that runs when the condition evaluates to false */
    scriptFalse?: string
    /** User interface to which the UI Policy applies */
    uiType?: uiType
    /** Whether to run the script in an isolated scope */
    isolateScript?: boolean
    /** Values to set when the UI Policy is applied */
    setValues?: string
    /**
     * View context where the UI Policy applies (sys_ui_view reference or name).
     * If global is true, the UI Policy applies to all form views.
     * If global is false/undefined, specify a view to make the policy view-specific.
     */
    view?: Record<'sys_ui_view'> | string
}>

/**
 * Creates a UI Policy that defines dynamic form behaviors to change field properties based on conditions.
 * UI  Policies can make fields mandatory, read-only, visible, hidden, or cleared when certain conditions are met.
 *
 * @see https://docs.servicenow.com/csh?topicname=ui-policy-api-now-ts.html&version=latest
 *
 * @param config - an object containing api properties:
 */
export function UiPolicy<const T extends TableName>(config: UiPolicy<T>): UiPolicy<T> {
    return config
}
